import json,numpy as np
p=np.load('p1.npy')
XL,mq,kiv,kpv,TVf,TQf,TPf,mp=[float(x) for x in p]
sub={
 "params":{"XL":XL,"mq":mq,"kiv":kiv,"kpv":kpv,"TVf":TVf,"TQf":TQf,"TPf":TPf,"mp":mp,"w0":2*np.pi*60},
 "defs":{
   "a":"(XL*Q0+V0**2)/V0",
   "b":"XL*P0/V0",
   "E0":"sqrt(a**2+b**2)",
   "Vcmd":"Vset + mq*(Q0 - Qm)",
   "Pout":"V*xv*sin(delta-theta)/XL",
   "Qout":"(V*xv*cos(delta-theta) - V**2)/XL"
 },
 "states":{
   "Pm":{"rhs":"(Pout-Pm)/TPf","init":"P0"},
   "Qm":{"rhs":"(Qout-Qm)/TQf","init":"Q0"},
   "Vm":{"rhs":"(V-Vm)/TVf","init":"V0"},
   "xv":{"rhs":"kiv*(Vcmd-Vm)","init":"E0"},
   "delta":{"rhs":"w0*mp*(P0-Pm)","init":"theta0+atan2(b,a)"}
 },
 "outputs":{"P":"Pout","Q":"Qout"}
}
json.dump(sub,open('submission.json','w'),indent=1)
